 public sealed class SignalUITests
 {
  string dir;GameRuntime game;
  [UnitySetUp]public IEnumerator Setup(){
#if UNITY_EDITOR
PortraitGameView.Set();
#endif
yield return null;dir=Path.Combine(Path.GetTempPath(),"unity-signal-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  void Prepare(){Debug.Log("PREPARED_SIGNAL_UI_STATE: elapsed active-drop progress only; no direct item or credit grant");game.Act(s=>{var n=s.Copy();n.Signals.progress=Signals.Interval(n);return n;});}
  [UnityTest]public IEnumerator VisibleLabSignalUsesRealClaimAndSavesExactlyOnce()
  {Prepare();yield return new WaitForSecondsRealtime(.2f);var button=GameObject.Find("LootSignal")?.GetComponent<Button>();Assert.That(button,Is.Not.Null);Assert.That(button.interactable,Is.True);Assert.That(button.GetComponent<RectTransform>().rect.height,Is.GreaterThanOrEqualTo(44));foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?568:width==390?844:932,"/tmp/unity-signals-prepared-"+width+".png");long components=game.State.Workshop.components.Sum();double count=game.State.Lifetime.dropsClaimed;yield return null;Canvas.ForceUpdateCanvases();var data=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,button.transform.position)};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(data,hits);File.WriteAllLines("/tmp/idle-signal-raycast.txt",hits.Select(h=>h.gameObject.name+" pos="+data.position+" mode="+button.GetComponentInParent<Canvas>().renderMode+" button="+button.transform.position+" root="+button.GetComponentInParent<Canvas>().rootCanvas.name));Assert.That(hits.Count,Is.GreaterThan(0));Assert.That(ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject),Is.EqualTo(button.gameObject),"Visible drone must be the first real raycast target");ExecuteEvents.Execute(button.gameObject,data,ExecuteEvents.pointerClickHandler);button.onClick.Invoke();Assert.That(game.State.Signals.visible,Is.Empty);Assert.That(game.State.Lifetime.dropsClaimed,Is.EqualTo(count+1));Assert.That(game.State.Workshop.components.Sum(),Is.GreaterThan(components));var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Lifetime.dropsClaimed,Is.EqualTo(count+1));Assert.That(loaded.State.Signals.visible,Is.Empty);yield return null;Assert.That(GameObject.Find("LootSignal"),Is.Null);}
  [UnityTest]public IEnumerator SignalSaveFailureKeepsRewardAndVisibleReceiptUnconsumed()
  {Prepare();yield return new WaitForSecondsRealtime(.2f);var button=GameObject.Find("LootSignal").GetComponent<Button>();double count=game.State.Lifetime.dropsClaimed;long components=game.State.Workshop.components.Sum();string id=game.State.Signals.visible.Single().id;File.WriteAllText(game.SavePath,"signal-damaged-original");button.onClick.Invoke();Assert.That(game.Writable,Is.False);Assert.That(game.State.Lifetime.dropsClaimed,Is.EqualTo(count));Assert.That(game.State.Workshop.components.Sum(),Is.EqualTo(components));Assert.That(game.State.Signals.visible.Single().id,Is.EqualTo(id));Assert.That(File.ReadAllText(game.SavePath),Is.EqualTo("signal-damaged-original"));}
  [UnityTest]public IEnumerator HitTargetTracksMotionAndReducedModeThenExpiryCannotReward(){Prepare();yield return new WaitForSecondsRealtime(.2f);var button=GameObject.Find("LootSignal").GetComponent<Button>();var first=button.transform.position;yield return new WaitForSecondsRealtime(.25f);Assert.That(button.transform.position,Is.Not.EqualTo(first));game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=true;return n;});yield return null;first=button.transform.position;yield return new WaitForSecondsRealtime(.25f);Assert.That(button.transform.position,Is.EqualTo(first));double count=game.State.Lifetime.dropsClaimed;string id=game.State.Signals.visible[0].id;game.Act(s=>Game.Advance(s,s.Signals.visible[0].expiresAt+1,false));yield return null;Assert.That(button.gameObject.activeSelf,Is.False);game.Act(s=>Signals.Claim(s,id,()=>.5));Assert.That(game.State.Lifetime.dropsClaimed,Is.EqualTo(count));}
  void ReviewState(){game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<8;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Credits=ScientificNumber.From(1000);n.Hardware[0]=4;n.Quality=n.Efficiency=1;n.Story.enabled=false;n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";n.Signals.visible=Array.Empty<LootSignal>();return n;});}
  [UnityTest]public IEnumerator ActualReceiptMatrixReducedMotionAndReload(){ReviewState();foreach(string language in new[]{"de","en"})foreach(int width in new[]{320,390,430}){game.Act(s=>SettingsRules.Change(s,"language",language));PortraitGameView.Set(width,width==320?694:width==390?846:932);Prepare();yield return new WaitForSecondsRealtime(.15f);Directory.CreateDirectory("/tmp/idle-drone-review");WorkshopTests.Capture(width,Screen.height,"/tmp/idle-drone-review/hanging-"+language+"-"+width+".png");var button=GameObject.Find("LootSignal").GetComponent<Button>();Assert.That(button.transform.Find("HangingParcel").GetComponent<Image>().sprite,Is.Not.Null);var timer=button.GetComponentInChildren<Text>().rectTransform;Assert.That(timer.anchoredPosition.x-timer.rect.width/2,Is.GreaterThan(19),"Countdown stays clear of parcel art");long materials=game.State.Workshop.components.Sum();double claims=game.State.Lifetime.dropsClaimed;button.onClick.Invoke();button.onClick.Invoke();Assert.That(game.State.Lifetime.dropsClaimed,Is.EqualTo(claims+1));var stage=game.GetComponent<RewardPresentation>().Current;Assert.That(stage.ReceiptKey,Does.StartWith("signal:"));Assert.That(stage.RewardCount,Is.GreaterThanOrEqualTo(2));yield return new WaitForSecondsRealtime(1.5f);WorkshopTests.Capture(width,Screen.height,"/tmp/idle-drone-review/reward-"+language+"-"+width+".png");Assert.That(game.State.Workshop.components.Sum(),Is.GreaterThan(materials));game.Show("research");Assert.That(stage.gameObject.activeSelf,Is.False);game.Show("hardware");}
   game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=true;return n;});Prepare();yield return null;GameObject.Find("LootSignal").GetComponent<Button>().onClick.Invoke();yield return null;var final=game.GetComponent<RewardPresentation>().Current;Assert.That(final.IsAnimating,Is.False);Assert.That(final.gameObject.activeSelf,Is.True,"Reduced motion keeps a readable static receipt");final.ShortenButton.onClick.Invoke();Assert.That(final.gameObject.activeSelf,Is.False,"Static receipt has a working close action");var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.State.Lifetime.dropsClaimed,Is.EqualTo(game.State.Lifetime.dropsClaimed));Assert.That(loaded.State.Workshop.components,Is.EqualTo(game.State.Workshop.components));}
  [UnityTest]public IEnumerator CoreDeliveryShowsAllSavedContents(){ReviewState();game.Act(s=>{var n=s.Copy();n.Research[Game.ResearchIndex("blueprints")]=1;n.Research[Game.ResearchIndex("materialAnalysis")]=10;n.Research[Game.ResearchIndex("blueprintAnalysis")]=5;n.Signals.visible=new[]{new LootSignal{id="review-core",spawnedAt=n.SavedAt,expiresAt=n.SavedAt+12000,variant=2,x=50,y=50,hasRewardFactor=true,rewardFactor=1}};return n;});yield return null;int draw=0;double[] rolls={0,.14,.28,.42,.56,.70,.84,0,.5,0};game.Act(s=>Signals.Claim(s,"review-core",()=>rolls[Math.Min(draw++,rolls.Length-1)]),"signal-claim");yield return new WaitForSecondsRealtime(1.6f);var stage=game.GetComponent<RewardPresentation>().Current;Assert.That(stage.RewardCount,Is.GreaterThanOrEqualTo(4));WorkshopTests.Capture(320,694,"/tmp/idle-drone-review/core-delivery-de-320.png");foreach(var label in stage.Rewards.GetComponentsInChildren<Text>()){var pos=stage.Stage.InverseTransformPoint(label.transform.position);Assert.That(Mathf.Abs(pos.y)+label.rectTransform.rect.height/2,Is.LessThan(stage.Stage.rect.height/2),label.text);Assert.That(label.cachedTextGenerator.lineCount,Is.LessThanOrEqualTo(3),label.text);}game.GetComponent<RewardPresentation>().Cancel();}
  [UnityTest]public IEnumerator RecordActualDelivery(){ReviewState();PortraitGameView.Set(390,846);game.Audio.Unlock();Prepare();yield return new WaitForSecondsRealtime(.2f);var node=new GameObject("DroneReviewAudio",typeof(AudioListener),typeof(ReviewAudioCapture));var previous=UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Where(a=>a.gameObject!=node).ToArray();foreach(var a in previous)a.enabled=false;var audio=node.GetComponent<ReviewAudioCapture>();audio.Begin();string folder="/tmp/idle-drone-review/motion";Directory.CreateDirectory(folder);var times=new List<string>();int frame=0;double start=Time.realtimeSinceStartupAsDouble;bool claimed=false;while(Time.realtimeSinceStartupAsDouble-start<6.5){double t=Time.realtimeSinceStartupAsDouble-start;if(t>=1&&!claimed){claimed=true;GameObject.Find("LootSignal").GetComponent<Button>().onClick.Invoke();}times.Add(t.ToString("R",System.Globalization.CultureInfo.InvariantCulture));WorkshopTests.Capture(390,846,folder+"/"+(frame++).ToString("D4")+".png");yield return null;}audio.Save(folder);File.WriteAllLines(folder+"/times.txt",times);foreach(var a in previous)if(a!=null)a.enabled=true;UnityEngine.Object.Destroy(node);Assert.That(game.State.Lifetime.dropsClaimed,Is.EqualTo(1));}


 }
}
